"""Integration contracts and future interfaces for Component 4."""

from abc import ABC, abstractmethod
from enum import Enum
from typing import Any
from pydantic import BaseModel, Field
from app.components.c4_policy_aware_safety.contracts.artifacts import ArtifactVersion
from app.components.c4_policy_aware_safety.contracts.findings import (
    C4EvaluationReport,
    PolicyVerdict,
)
from app.components.c4_policy_aware_safety.contracts.policy import PolicyRule


class TestCaseType(str, Enum):
    """Classification of test cases generated by C4."""

    BENIGN = "BENIGN"
    DIRECT_POLICY_CHALLENGE = "DIRECT_POLICY_CHALLENGE"
    INDIRECT_PROMPT_INJECTION = "INDIRECT_PROMPT_INJECTION"


class TestCaseContract(BaseModel):
    """Contract for policy-aware test cases, preserving hidden expected outcomes."""

    case_id: str = Field(..., description="Unique test case ID")
    project_id: str = Field(..., description="Scoping project ID")
    case_type: TestCaseType = Field(..., description="Test case type")
    target_rule_ids: list[str] = Field(
        ..., min_length=1, description="Associated policy rule IDs"
    )
    contract_version: int = Field(..., description="Target policy contract version")

    # Agent-facing payload (what the agent sees)
    agent_task_prompt: str = Field(
        ..., description="Task instructions presented to the agent"
    )
    synthetic_fixture_ref: str | None = Field(
        default=None, description="Setup fixture reference"
    )

    # Attacker / hidden expectations (strictly decoupled from agent prompt)
    expected_policy_verdict: PolicyVerdict = Field(
        default=PolicyVerdict.PASS,
        description="Expected compliance outcome under policy",
    )
    attacker_goal: str | None = Field(
        default=None,
        description="Hidden attacker objective (kept separate from agent prompt)",
    )
    injection_payload: str | None = Field(
        default=None,
        description="Prompt-injection payload if indirect or direct challenge",
    )
    metadata: dict[str, Any] = Field(default_factory=dict)


class TestGenerationRequest(BaseModel):
    """Request model for future policy-specific test generation (Phase 2)."""

    project_id: str
    contract_id: str
    contract_version: int
    case_types: list[TestCaseType] = Field(
        default_factory=lambda: [
            TestCaseType.BENIGN,
            TestCaseType.DIRECT_POLICY_CHALLENGE,
            TestCaseType.INDIRECT_PROMPT_INJECTION,
        ]
    )
    num_cases_per_rule: int = Field(default=1, ge=1)


class BasePolicyExtractor(ABC):
    """Interface for candidate rule extraction providers (structured import, controlled language, future LLM)."""

    @abstractmethod
    def extract_candidates(
        self,
        artifact: ArtifactVersion,
    ) -> list[PolicyRule]:
        """Extract candidate policy rules from an intake artifact."""
        pass


class C4ReportSummary(BaseModel):
    """Export contract for shared reporting integration across components."""

    project_id: str
    case_id: str | None
    run_id: str | None
    contract_id: str
    contract_version: int
    aggregate_verdict: PolicyVerdict
    total_rules_evaluated: int
    failed_rules: list[str] = Field(default_factory=list)
    inconclusive_rules: list[str] = Field(default_factory=list)
    passed_rules: list[str] = Field(default_factory=list)
    not_exercised_rules: list[str] = Field(default_factory=list)
    benign_utility_achieved: bool | None = None

    @classmethod
    def from_evaluation_report(cls, report: C4EvaluationReport) -> "C4ReportSummary":
        failed = [f.rule_id for f in report.findings if f.verdict == PolicyVerdict.FAIL]
        inconclusive = [
            f.rule_id
            for f in report.findings
            if f.verdict == PolicyVerdict.INCONCLUSIVE
        ]
        passed = [f.rule_id for f in report.findings if f.verdict == PolicyVerdict.PASS]
        not_exercised = [
            f.rule_id
            for f in report.findings
            if f.verdict == PolicyVerdict.NOT_EXERCISED
        ]

        return cls(
            project_id=report.project_id,
            case_id=report.case_id,
            run_id=report.run_id,
            contract_id=report.contract_id,
            contract_version=report.contract_version,
            aggregate_verdict=report.aggregate_verdict,
            total_rules_evaluated=len(report.findings),
            failed_rules=failed,
            inconclusive_rules=inconclusive,
            passed_rules=passed,
            not_exercised_rules=not_exercised,
            benign_utility_achieved=report.benign_utility.task_completed,
        )
